package solution

import (
	"strconv"
	"strings"
)

// parse turns "v1.4.0" into [1, 4, 0].
func parse(v string) [3]int {
	v = strings.TrimPrefix(v, "v")        // drop the leading 'v'
	parts := strings.Split(v, ".")        // ["1", "4", "0"]
	var out [3]int
	for i := 0; i < 3 && i < len(parts); i++ {
		n, _ := strconv.Atoi(parts[i])    // tolerate well-formed input
		out[i] = n
	}
	return out
}

// Less reports whether semver a < b, comparing major, then minor, then patch.
func Less(a, b string) bool {
	pa, pb := parse(a), parse(b)
	for i := 0; i < 3; i++ {
		if pa[i] != pb[i] {
			return pa[i] < pb[i]  // first differing component decides
		}
	}
	return false                          // equal => not strictly less
}

