package solution

import "testing"

func TestLess(t *testing.T) {
	cases := []struct {
		a, b string
		want bool
	}{
		{"v1.2.0", "v1.5.0", true},
		{"v1.5.0", "v1.2.0", false},
		{"v1.4.0", "v1.4.0", false},
		{"v1.9.0", "v2.0.0", true},
		{"v2.0.1", "v2.0.0", false},
	}
	for _, c := range cases {
		if got := Less(c.a, c.b); got != c.want {
			t.Errorf("Less(%q,%q)=%v want %v", c.a, c.b, got, c.want)
		}
	}
}

